import{_ as h,l,o as e,c as r,v as i,p as n,x as t,d as A,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"高 NA 的产能与经济","description":"","frontmatter":{"title":"高 NA 的产能与经济","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/high-na-throughput-economics.md","filePath":"litho/high-na-throughput-economics.md","lastUpdated":1789023840000}'),E={name:"litho/high-na-throughput-economics.md"};function c(d,a,N,u,_,g){const o=l("Mermaid");return e(),r("div",null,[a[1]||(a[1]=i('<h1 id="高-na-的产能与经济" tabindex="-1">高 NA 的产能与经济 <a class="header-anchor" href="#高-na-的产能与经济" aria-label="Permalink to &quot;高 NA 的产能与经济&quot;">​</a></h1><div class="epigraph"><p>0.55 NA 把单次节距往下推，也把场切成半场、把胶涂薄、把源功率再要一档。产能是半场拼接、剂量和可用性乘出来的，不是 NA 的线性奖励。</p><footer>—— 据 van Schoot、ASML 对 EXE / High-NA 生产力的公开讨论</footer></div><p><a href="/litho/euv-single-expose-limit">上一课</a>把 0.33 单次墙钉在 NILS 与随机上。缺口是：抬 NA 买更小节距，工厂要付什么。本课钉 High-NA 的产能与经济。EUV 进阶课序收到这里；下一课程从版图数据到掩模制造另起，不在本课重写 GDS 或 DUV 掩模厂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>单次极限课给出三条出路。High-NA 是其中最重资产的一条：硅片侧 NA 0.55、变形倍率、半场扫描、更紧焦深、更薄胶、往往更高剂量。IF 功率路线往 500 W–1 kW 的公开目标，很大一块是为这张账服务。半场意味着同样芯片面积要更多次扫描拼接，<a href="/litho/high-na-overlay-na">套刻</a> 与 <a href="/litho/high-na-stitch">stitch</a> 吃良率；名义 wph 不能按 0.33 全场线性外推。</p><p>缺口是把这些税加总，而不是再推一遍瑞利。经济比较的对象是：High-NA 单次 vs 0.33 多重 EUV vs 继续浸没，在掩模张数、工艺步、良率和资本之间。</p><p><span class="marginnote">不要把产品页 wph 抄成物理上限。声明的剂量、场利用率、可用性一变，数字立刻变。本课只保留公开的结构关系。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>产能：\\(TPT \\propto\\) 可用功率 / 剂量 × 场面积 / 扫描开销 × 可用性。High-NA：场面积约半，剂量可能升，开销含拼接与更密对准，可用性含源、膜、收集镜。源功率必须先把半场和 \\(T^2\\) 补回，才谈「比 0.33 更快」。</p><p>成本：工具资本、厂务电力（CO₂ 链墙插）、掩模（变形、更严 CDU、pellicle）、胶与硬掩模栈。掩模侧 8×/4× 变形让版图和 MDP 规则改变——具体 GDS/OASIS、分层和 fracturing 由下一课程写，本课只指出：High-NA 把掩模数据准备从可选项变成产能链的一环，版图错误会直接浪费半场扫描。</p><h3 id="和-0-33-多重比的是步数税" tabindex="-1">和 0.33 多重比的是步数税 <a class="header-anchor" href="#和-0-33-多重比的是步数税" aria-label="Permalink to &quot;和 0.33 多重比的是步数税&quot;">​</a></h3><p>双重 EUV 或切层要两张版、两次对准、两倍随机机会。High-NA 单次用资本和半场换回步数。交叉点随源可用性、pellicle 破膜率和拼接良率移动。没有可维持的千瓦源，交叉点会滑回 0.33 多重——功率路线课在经济上的落点。</p>',12)),(e(),n(p,null,{default:t(()=>[s(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20NA%5B%22NA%200.55%20%E5%8D%95%E6%AC%A1%E8%8A%82%E8%B7%9D%22%5D%20--%3E%20HALF%5B%22%E5%8D%8A%E5%9C%BA%E6%89%AB%E6%8F%8F%22%5D%0A%20%20HALF%20--%3E%20TPT%5B%22%E4%BA%A7%E8%83%BD%22%5D%0A%20%20D%5B%22%E6%9B%B4%E9%AB%98%E5%89%82%E9%87%8F%20%2F%20%E8%96%84%E8%83%B6%22%5D%20--%3E%20TPT%0A%20%20SRC%5B%22IF%20%E5%8A%9F%E7%8E%87%E4%B8%8E%E5%8F%AF%E7%94%A8%E6%80%A7%22%5D%20--%3E%20TPT%0A%20%20MASK%5B%22%E6%9B%B4%E4%B8%A5%E6%8E%A9%E6%A8%A1%E4%B8%8E%20pellicle%22%5D%20--%3E%20COST%5B%22%E5%B1%82%E6%88%90%E6%9C%AC%22%5D%0A%20%20TPT%20--%3E%20COST%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=i('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>光学增益来自 NA，系统损失来自 \\(R^N\\)、半场、变形照明足迹和随机剂量。van Schoot 等把 High-NA 写成成像与系统的联合设计：没有 1 kW 级可维持源和可用 pellicle，NA 只是更贵的低产机。经济上，当 0.33 多重的掩模张数、套刻和缺陷超过 High-NA 半场税时，插入才合理——与层数课的插入逻辑同一把尺，刻度换成资本。</p><p><span class="marginnote">EUV 进阶到此收束光源–光学–掩模部件–胶转印–节点经济。掩模制造课程从数据格式起笔，不再重讲 pellicle 物理或锡滴 LPP。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 GDSII 与 OASIS 的记录结构，那是下一课程第一课。不重写 DUV 掩模坯、铬膜、雾化。不编造 EXE 出货片/小时。出处：van Schoot High-NA；ASML EXE 生产力公开材料；功率路线与单次极限课。</p><p>后课默认：说到 High-NA「值不值」，先问半场 TPT、剂量、源可用性和掩模成本，再问 NA 数字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>High-NA 用 NA 换节距，用半场、剂量、源功率和掩模严规格付钱。</li><li>产能会计与 0.33 相同结构，系数更苛刻；比较对象是多重 EUV 的步数税。</li><li>本课程结束。下一课程进入掩模制造与数据准备，从版图文件格式起，不回头重写本课的膜与源。</li><li>出处：van Schoot；ASML High-NA 公开讨论；本课序功率与单次极限。</li></ul>',8))])}const S=h(E,[["render",c]]);export{T as __pageData,S as default};
